from typing import List

def plusMultArray(A: List[int]) -> str:
    def evaluate(vals: List[int]) -> int:
        if not vals:
            return 0
        r = vals[0] % 2
        for k, v in enumerate(vals[1:]):
            # 运算符交替：先乘、再加、再乘……全程只保留奇偶
            r = (r * v) % 2 if k % 2 == 0 else (r + v) % 2
        return r

    r_even = evaluate(A[0::2])
    r_odd = evaluate(A[1::2])
    if r_odd > r_even:
        return "ODD"
    if r_even > r_odd:
        return "EVEN"
    return "NEUTRAL"
